`define CYCLE_TIME 10.0

`ifndef SEED_NUMBER
  `define SEED_NUMBER 75364589
`endif

`ifndef PATTERN_NUMBER
  `define PATTERN_NUMBER 5000
`endif

`protect
// Color codes
`define C_RST     "\033[0m"
`define CX_BLUE   "\033[38;5;123m" // Light Sky Blue
`define CX_GREEN  "\033[38;5;121m" // Pale Green
`define CX_PURPLE "\033[38;5;183m" // Lavender
`define CX_YELLOW "\033[38;5;226m" // Yellow
`define CX_ORANGE "\033[38;5;215m" // Peach
`define CX_RED    "\033[38;5;196m" // Red

module PATTERN (
  // Output Signals
  output logic clk,
  output logic rst_n,

  output logic [7:0]  up_req,
  output logic [7:0]  down_req,
  output logic [23:0] car_req,
  output logic [2:0]  btn_open,
  output logic [2:0]  btn_close,
  output logic [11:0] pax_cnt,

  // Input Signals
  input [8:0] cur_floor,
  input [8:0] lift_status,
  input [5:0] serve_dir,
  input [2:0] is_full
);
//================================================================
// Clock
//================================================================
real CYCLE = `CYCLE_TIME;
always #(CYCLE/2.0) clk = ~clk;
//================================================================
// Parameter & Declaration
//================================================================
localparam logic [2:0] IDLE = 3'b000, MOVING  = 3'b001, OPENING = 3'b010,
                       OPEN = 3'b011, CLOSING = 3'b100;

localparam logic [1:0] NONE = 2'b00, UP = 2'b01, DOWN = 2'b10, INVALID = 2'b11;

localparam int HIGH_DENSITY = 2, MED_DENSITY = 1, LOW_DENSITY = 0;

function automatic string get_status(logic [2:0] status);
  case(status)
    IDLE:    return "   IDLE";
    MOVING:  return " MOVING";
    OPENING: return "OPENING";
    OPEN:    return "   OPEN";
    CLOSING: return "CLOSING";
    default: return "UNKNOWN";
  endcase
endfunction

function automatic string get_floor(logic [2:0] floor);
  if (floor == 3'b000)
    return "B1";
  else
    return $sformatf("%1dF", floor);
endfunction

localparam int TIMEOUT = 2000;

int SEED;
int pat_cnt;
int i, j, k;

// Traffic State Variables
int cur_density;
int density_duration;

// Unpacked signals for easier indexing in loops
logic [2:0] c_floor[3];
logic [2:0] status[3];
logic [1:0] s_dir[3];

assign {c_floor[2], c_floor[1], c_floor[0]} = cur_floor;
assign {status[2], status[1], status[0]} = lift_status;
assign {s_dir[2], s_dir[1], s_dir[0]} = serve_dir;

// History tracking for verification
logic [2:0] prev_status[3];
logic [2:0] prev_floor[3];
logic [1:0] prev_dir[3];
int status_timer[3];
int floor_timer[3];

//================================================================
// Object & Queue Definition (Scoreboard)
//================================================================
class Passenger;
  int id;
  int src;
  int dst;
  logic [1:0] dir;
  int spawn_time;
  int board_time;

  function new(int _id, int _src, int _dst, int _time);
    id = _id;
    src = _src;
    dst = _dst;
    spawn_time = _time;
    board_time = -1;
    dir = (dst > src) ? UP : DOWN;
  endfunction
endclass

Passenger waiting_q[$]; // Passengers waiting at halls
Passenger car_q[3][$];  // Passengers inside the 3 elevators
int lat, total_latency;
int done_cnt;

Passenger p; // Temporary object inside loop

class dice_c;
  int min, max;
  rand int val;
  constraint range { val inside{[min:max]}; }

  function new(int _min = 0, int _max = 5);
    min = (_min >= _max) ? _max : _min;
    max = (_min >= _max) ? _min : _max;
    this.srandom(`SEED_NUMBER);
  endfunction

  function int randomize_range(int a, int b);
    min = (a >= b) ? b : a;
    max = (a >= b) ? a : b;
    return this.randomize();
  endfunction
endclass
dice_c pax_dice, btn_dice;

//================================================================
// Main flow
//================================================================
initial begin
  reset_task();
  for(pat_cnt = 0; pat_cnt < `PATTERN_NUMBER; pat_cnt++) begin
    gen_pax_task();
  end
  wait_all_done();
  YOU_PASS_task();
end

//================================================================
// Continuous Check & Scoreboard
//================================================================
initial begin
  wait(rst_n === 1'b0);
  wait(rst_n === 1'b1);

  // Initialize histories
  for (int e = 0; e < 3; e++) begin
    prev_status[e]  = IDLE;
    prev_floor[e]   = c_floor[e];
    prev_dir[e]     = s_dir[e];
  end

  forever begin
      @(negedge clk);

    //----------------------------------------------------------------
    // Timeout Constraints Check
    //----------------------------------------------------------------
    foreach (waiting_q[k]) begin
      if (($time - waiting_q[k].spawn_time) / `CYCLE_TIME >= TIMEOUT)
        fail('{
          "                 Timeout Violation                ",
          $sformatf("     Passenger %4d waited for %4d+ cycles!", waiting_q[k].id, TIMEOUT)
        });
    end

    for (int e = 0; e < 3; e++) begin
      foreach (car_q[e][k]) begin
        if (($time - car_q[e][k].board_time) / `CYCLE_TIME >= TIMEOUT)
          fail('{
            "                 Timeout Violation                ",
            $sformatf("   Passenger %4d stuck in E%1d for %4d+ cycles!", car_q[e][k].id, e, TIMEOUT)
          });
      end
    end

    for (int e = 0; e < 3; e++) begin
      //----------------------------------------------------------------
      // Overload Check
      //----------------------------------------------------------------
      if (pax_cnt[e*4 +: 4] === 4'd15 && is_full[e] !== 1'b1)
        fail('{
          "   is_full not raise when elevator is overloaded  ",
          $sformatf("    E%1d is overloaded (%2d/15) but is_full is low!", e, pax_cnt[e*4 +: 4])
        });

      //----------------------------------------------------------------
      // No Teleportation
      //----------------------------------------------------------------
      if (c_floor[e] !== prev_floor[e]) begin
        if (status[e] !== MOVING)
          fail('{
            "     Elevator cannot move outside MOVING state    ",
            $sformatf("   E%1d moved from %s to %s but status is %s", e, get_floor(prev_floor[e]), get_floor(c_floor[e]), get_status(status[e]))
          });
        if (floor_timer[e] < 10)
          fail('{
            "        Floor changed faster than 10 cycles       ",
            $sformatf("        E%1d moved from %s to %s in %2d cycles", e, get_floor(prev_floor[e]), get_floor(c_floor[e]), floor_timer[e])
          });
        // Check if step is exactly +1 or -1 corresponding to serve_dir
        if (prev_dir[e] === UP && c_floor[e] !== prev_floor[e] + 1)
          fail('{
            "        Floor step must be +1 for going UP        ",
            $sformatf("              E%1d moved from %s to %s", e, get_floor(prev_floor[e]), get_floor(c_floor[e]))
          });
        if (prev_dir[e] === DOWN && c_floor[e] !== prev_floor[e] - 1)
          fail('{
            "       Floor step must be -1 for going DOWN       ",
            $sformatf("              E%1d moved from %s to %s", e, get_floor(prev_floor[e]), get_floor(c_floor[e]))
          });

        floor_timer[e] = 1;
        prev_floor[e] = c_floor[e];
      end else if (floor_timer[e] != '1) begin
        floor_timer[e]++;
      end

      //----------------------------------------------------------------
      // FSM Timing Constraint Check
      //----------------------------------------------------------------
      if (status[e] !== prev_status[e]) begin
        // Check illegal transitions
        if ((prev_status[e] === IDLE    && (status[e] === OPENING || status[e] === OPEN || status[e] === CLOSING)) ||
            (prev_status[e] === MOVING  && (status[e] === OPEN || status[e] === CLOSING)) ||
            (prev_status[e] === OPENING && (status[e] === MOVING || status[e] === CLOSING)) ||
            (prev_status[e] === OPEN    && (status[e] === MOVING || status[e] === OPENING)) ||
            (prev_status[e] === CLOSING && ((status[e] === OPENING && !btn_open[e]) || status[e] === OPEN))) begin
          fail('{
            "                Invalid transition                ",
            $sformatf("              E%1d: %s -> %s", e, get_status(prev_status[e]), get_status(status[e]))
          });
        end
        // Check outgoing constraints
        if (prev_status[e] === OPENING && status_timer[e] < 5)
          fail('{
            $sformatf("       E%1d: OPENING takes less than 5 cycles       ", e)
          });
        if (prev_status[e] === CLOSING && status_timer[e] < 5)
          fail('{
            $sformatf("       E%1d: CLOSING takes less than 5 cycles       ", e)
          });
        // T_WAIT check (20 cycles) for OPEN state
        if (prev_status[e] === OPEN && status_timer[e] < 20)
          fail('{
            $sformatf("        E%1d: OPEN takes less than 20 cycles        ", e)
          });

        status_timer[e] = 1;
      end else if (status_timer[e] != '1) begin
        status_timer[e]++;
      end

      //----------------------------------------------------------------
      // Direction Change Check
      //----------------------------------------------------------------
      if (s_dir[e] === NONE && status[e] !== IDLE) begin
        fail('{
          "       serve_dir is 2'b00 when not at IDLE        ",
          $sformatf("                   E%1d: %s", e, get_status(status[e]))
        });
      end
      if (s_dir[e] !== prev_dir[e]) begin
        if (status[e] === OPENING || status[e] === CLOSING)
          fail('{
            "      serve_dir changed during door operation     ",
            $sformatf("           E%1d: 2'b%2b -> 2'b%2b at %s", e, prev_dir[e], s_dir[e], get_status(status[e]))
          });
        if (s_dir[e] === INVALID)
          fail('{
            $sformatf("         E%1d: serve_dir == 2'b11 is invalid        ", e)
          });
      end

      //----------------------------------------------------------------
      // Scoreboard: Passenger Boarding, Alighting & Input Updating
      //----------------------------------------------------------------

      // Passengers get off, car_req falls (edge trigger: OPENING -> OPEN)
      if (prev_status[e] === OPENING && status[e] === OPEN) begin
        car_req[e*8 + c_floor[e]] = 1'b0; // Fall car_req for this floor

        for (int k = 0; k < car_q[e].size(); k++) begin
          p = car_q[e][k];
          if (p.dst == c_floor[e]) begin
            lat = ($time - p.spawn_time) / `CYCLE_TIME;
            total_latency += lat;
            done_cnt++;
            car_q[e].delete(k);
            $write("[%s%t%s] ", `CX_ORANGE, $realtime, `C_RST);
            $display("%sPassenger No.%4d gets off E%1d at %s (latency: %5d)%s", `CX_GREEN, p.id, e, get_floor(c_floor[e]), lat, `C_RST);
            k--; // Adjust index after deletion
          end
        end
        pax_cnt[e*4 +: 4] = car_q[e].size();
      end

      // Passengers get in, car_req raises & Hall requests fall (edge trigger: OPEN -> CLOSING)
      if (prev_status[e] === OPEN && status[e] === CLOSING) begin
        for (int k = 0; k < waiting_q.size(); k++) begin
          p = waiting_q[k];
          if (p.src == c_floor[e] && p.dir == s_dir[e]) begin
            // Check capacity limits and Bypass Mode (is_full)
            if (car_q[e].size() < 15 && is_full[e] === 1'b0) begin
              p.board_time = $time;
              car_q[e].push_back(p);
              car_req[e*8 + p.dst] = 1'b1; // Raise destination req
              waiting_q.delete(k);
              $write("[%s%t%s] ", `CX_ORANGE, $realtime, `C_RST);
              $display("%sPassenger No.%4d gets in E%1d at %s%s", `CX_PURPLE, p.id, e, get_floor(c_floor[e]), `C_RST);
              k--; // Adjust index after deletion
            end
          end
        end
        pax_cnt[e*4 +: 4] = car_q[e].size();

        if (s_dir[e] == UP)   up_req[c_floor[e]] = 1'b0;
        if (s_dir[e] == DOWN) down_req[c_floor[e]] = 1'b0;

        // Re-check if someone was left behind (e.g., due to full capacity) and raise again
        foreach (waiting_q[k]) begin
          if (waiting_q[k].src == c_floor[e]) begin
            if (waiting_q[k].dir == UP)   up_req[c_floor[e]] = 1'b1;
            if (waiting_q[k].dir == DOWN) down_req[c_floor[e]] = 1'b1;
          end
        end
      end

      //----------------------------------------------------------------
      // Button Interruption Injection
      //----------------------------------------------------------------
      if (!btn_dice.randomize_range(0, 99))
        $fatal(1, $sformatf("%sRandomization failed for class \"btn_dice\"%s", `CX_RED, `C_RST));

      if (prev_status[e] === OPEN && status[e] === OPEN) begin
        // 4% chance to press a button per cycle to test interrupts (2% each)
        btn_open[e]  = (btn_dice.val < 2);
        btn_close[e] = (btn_dice.val >= 2 && btn_dice.val < 4);
      end else if (prev_status[e] === CLOSING && status[e] === CLOSING) begin
        // 2% chance to press open during closing to test reopening
        btn_open[e] = (btn_dice.val < 2);
      end else begin
        btn_open[e]  = 1'b0;
        btn_close[e] = 1'b0;
      end

      if (status[e] === OPEN && btn_open[e])
        status_timer[e] = 0; // Reset timer if open button is pressed
      else if (status[e] === OPEN && btn_close[e])
        status_timer[e] = 20; // Satisfy timer check if close button is pressed
      else if (status[e] === CLOSING && btn_open[e])
        status_timer[e] = 5; // Satisfy timer check if open button is pressed

      //----------------------------------------------------------------
      // Status Update
      //----------------------------------------------------------------
      prev_status[e] = status[e];
      prev_dir[e]    = s_dir[e];
    end
  end
end

//================================================================
// Task
//================================================================
task reset_task();
  SEED = `SEED_NUMBER;
  rst_n = 1'b1;

  up_req    = 8'h00;
  down_req  = 8'h00;
  car_req   = 24'h00_00_00;
  btn_open  = 3'b000;
  btn_close = 3'b000;
  pax_cnt   = 12'h000;

  total_latency = 0;
  done_cnt = 0;
  density_duration = 0;
  waiting_q.delete();
  for(int e = 0; e < 3; e++)
    car_q[e].delete();

  pax_dice = new();
  btn_dice = new();

  $timeformat(-9, 1, " ns", 15);

  force clk = 1'b0;
  #(CYCLE * ($random(SEED) % 'd3 + 'd1)); rst_n = 1'b0;
  #(CYCLE * 0.75);

  // Initial check
  if (lift_status !== 9'd0 || serve_dir !== 6'd0 || is_full !== 3'd0) begin
    fail('{
      "           output must be 0 after reset           "
    });
  end
  if (cur_floor === 9'dx) begin
    fail('{
      "     cur_floor must not be unknown after reset    "
    });
  end

  #(CYCLE * 0.25); rst_n = 'b1;
  #(CYCLE); release clk;
  repeat($random(SEED) % 'd10 + 'd5) @(negedge clk);
endtask

task gen_pax_task();
  Passenger p;
  int src, dst;
  int delay;

  // Randomly generate passenger src and dst
  src = $random(SEED) % 'd8;
  do begin
    dst = $random(SEED) % 'd8;
  end while (src == dst);

  // Push to queue
  p = new(pat_cnt, src, dst, $time);
  waiting_q.push_back(p);

  // Raise hall request
  if (p.dir == UP)   up_req[src] = 1'b1;
  else             down_req[src] = 1'b1;

  $write("[%s%t%s] ", `CX_ORANGE, $realtime, `C_RST);
  $display("%sPassenger No.%4d requests to go from %s to %s%s", `CX_BLUE, p.id, get_floor(src), get_floor(dst), `C_RST);

  // ----------------------------------------------------------------
  // Traffic Density State Machine
  // ----------------------------------------------------------------
  if (density_duration == 0) begin
    if (!pax_dice.randomize_range(0, 99))
      $fatal(1, $sformatf("%sRandomization failed for class \"pax_dice\"%s", `CX_RED, `C_RST));

    if (pax_dice.val < 25) begin
      // 25% chance for High Density (Overload)
      cur_density = HIGH_DENSITY;
      density_duration = $random(SEED) % 'd51 + 'd50; // Persist for 50~100 passengers
    end else if (pax_dice.val < 85) begin
      // 60% chance for Medium Density (Balanced)
      cur_density = MED_DENSITY;
      density_duration = $random(SEED) % 'd51 + 'd50; // Persist for 50~100 passengers
    end else begin
      // 15% chance for Low Density (Idle)
      cur_density = LOW_DENSITY;
      density_duration = $random(SEED) % 'd6 + 'd5; // Persist for 5~10 passengers
    end
  end
  density_duration--;

  // ----------------------------------------------------------------
  // Apply Delay Based on Current Density
  // ----------------------------------------------------------------
  if (cur_density == HIGH_DENSITY) begin
    // Spawning 1 pax every 1~4 cycles
    delay = $random(SEED) % 'd4 + 'd1;
  end else if (cur_density == MED_DENSITY) begin
    // Spawning 1 pax every 10~20 cycles
    delay = $random(SEED) % 'd11 + 'd10;
  end else begin
    // Spawning 1 pax every 150~300 cycles
    delay = $random(SEED) % 'd151 + 'd150;
    // Inject occasional extreme idle periods (15%)
    if ($random(SEED) % 'd100 < 15) delay += 'd200;
  end

  repeat(delay) @(negedge clk);
endtask

task wait_all_done();
  wait(done_cnt === `PATTERN_NUMBER);
  repeat(10) @(negedge clk);
endtask

//================================================================
// ASCII Art
//================================================================

task YOU_PASS_task();
